import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';

export type ServiceType = 'boarding' | 'daycare';

export interface BookingFormValue {
  fullName: string;
  phone: string;
  petName: string;
  breed: string;
  age: string;
  specialCare: string;
  service: ServiceType;
  checkIn: string;
  checkOut: string;
  message: string;
}

export const SERVICE_LABELS: Record<ServiceType, string> = {
  boarding: 'Overnight Boarding',
  daycare: 'Dog Day Care',
};

/** Indian mobile: optional +91 / 91 / 0 prefix followed by 10 digits starting 6–9. */
const INDIAN_MOBILE = /^(?:\+91|91|0)?[6-9]\d{9}$/;

/** Letters (any script), spaces and common name punctuation. */
export const NAME_PATTERN = /^[\p{L}][\p{L} .'-]*$/u;

/** Breed names may also include digits, ampersand, slash and brackets (e.g. "Lab / Mix"). */
export const BREED_PATTERN = /^[\p{L}\d][\p{L}\d .'&/()-]*$/u;

/** Returns today's local date as YYYY-MM-DD (lexicographically comparable). */
export function todayIso(): string {
  return toIsoDate(new Date());
}

/** Formats a Date as local YYYY-MM-DD. */
export function toIsoDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** Latest selectable date (one year ahead) — guards against typos like year 20266. */
export function maxBookingIso(): string {
  const d = new Date();
  d.setFullYear(d.getFullYear() + 1);
  return toIsoDate(d);
}

/** Validates an Indian mobile number, ignoring spaces and dashes. */
export const indianPhoneValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
  const raw = String(control.value ?? '').replace(/[\s-]/g, '');
  if (!raw) return null;
  return INDIAN_MOBILE.test(raw) ? null : { indianPhone: true };
};

/** Validates a YYYY-MM-DD date is well-formed, not in the past and within the booking window. */
export const bookingDateValidator: ValidatorFn = (control: AbstractControl): ValidationErrors | null => {
  const value = String(control.value ?? '');
  if (!value) return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value) || Number.isNaN(Date.parse(value))) return { invalidDate: true };
  if (value < todayIso()) return { pastDate: true };
  if (value > maxBookingIso()) return { tooFar: true };
  return null;
};

/** Form-group validator: overnight check-out must be after check-in. */
export const dateOrderValidator: ValidatorFn = (group: AbstractControl): ValidationErrors | null => {
  const service = group.get('service')?.value as ServiceType;
  const checkIn = group.get('checkIn')?.value as string;
  const checkOut = group.get('checkOut')?.value as string;
  if (service !== 'boarding' || !checkIn || !checkOut) return null;
  return checkOut > checkIn ? null : { dateOrder: true };
};

/** Collapses whitespace in single-line input. */
function oneLine(value: string): string {
  return value.replace(/\s+/g, ' ').trim();
}

/** Trims multi-line input and limits consecutive blank lines. */
function multiLine(value: string): string {
  return value.replace(/\r\n?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
}

/** Formats YYYY-MM-DD as e.g. "15 December 2026" without timezone shifts. */
export function formatLongDate(iso: string): string {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d).toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });
}

/**
 * Builds the plain-text WhatsApp enquiry. The caller must URL-encode the result
 * (whatsappUrl() does this with encodeURIComponent).
 */
export function buildBookingMessage(v: BookingFormValue): string {
  const isBoarding = v.service === 'boarding';
  const lines = [
    `Hello! I would like to enquire about ${isBoarding ? 'pet boarding' : 'dog day care'}.`,
    '',
    `Pet Parent: ${oneLine(v.fullName)}`,
    `Phone: ${oneLine(v.phone)}`,
    `Pet Name: ${oneLine(v.petName)}`,
    `Breed: ${oneLine(v.breed)}`,
  ];
  if (v.age.trim()) lines.push(`Age: ${oneLine(v.age)}`);
  lines.push(`Service: ${SERVICE_LABELS[v.service]}`);
  if (isBoarding) {
    lines.push(`Check-in: ${formatLongDate(v.checkIn)}`, `Check-out: ${formatLongDate(v.checkOut)}`);
  } else {
    lines.push(`Date: ${formatLongDate(v.checkIn)}`);
  }
  if (v.specialCare.trim()) lines.push(`Special Requirements: ${multiLine(v.specialCare)}`);
  if (v.message.trim()) lines.push(`Message: ${multiLine(v.message)}`);
  lines.push('', 'Please confirm availability and pricing. Thank you!');
  return lines.join('\n');
}
